import { z } from 'zod';

export const schema = z.object({
  name: z
    .string()
    .min(2, 'Name must be at least 2 characters')
    .meta({ title: 'Name', examples: ['Jane Doe'] }),
  email: z
    .string()
    .email('Please enter a valid email')
    .meta({ title: 'Email', examples: ['jane@example.com'] }),
  age: z.number().min(18, 'Must be at least 18').optional().meta({ title: 'Age' }),
  subscribe: z.boolean().default(false).meta({ title: 'Subscribe to updates' })
});

import { defineConfig, SHADCN_OVERRIDES } from '@zod-to-form/core';

import type * as Components from '@/components/zod-form-components';
import type * as ZodSchemas from './schema';

export default defineConfig<typeof Components, typeof ZodSchemas>({
  components: {
    source: '@/components/zod-form-components',
    preset: 'shadcn',
    overrides: {
      ...SHADCN_OVERRIDES
    }
  },
  defaults: {
    mode: 'submit',
    ui: 'shadcn',
    overwrite: false,
    serverAction: false,
    formProvider: false,
    // optimization: { level: 2 }  // 1 = decompose, 2 = native rules, 3 = cross-field
  },
  include: [],
  exclude: [],
  schemas: {
    schema: {}
  }
});

